import numpy as np
L=open('opt.xyz').read().split('\n'); n=int(L[0])
els=[];P=[]
for l in L[2:2+n]:
    s=l.split(); els.append(s[0]); P.append(list(map(float,s[1:4])))
P=np.array(P)
# check connectivity same as init
def bonds(P,els):
    b=set()
    for i in range(n):
        for j in range(i+1,n):
            r=np.linalg.norm(P[i]-P[j]); cut=2.5 if 'Ir' in (els[i],els[j]) else (1.3 if 'H' in (els[i],els[j]) else 1.75)
            if r<cut: b.add((i,j))
    return b
L0=open('init.xyz').read().split('\n'); P0=np.array([list(map(float,l.split()[1:4])) for l in L0[2:2+n]])
b0=bonds(P0,els); b1=bonds(P,els)
print("lost",b0-b1,"new",b1-b0)
print("Ir-Ir",np.linalg.norm(P[0]-P[23]))
for i in range(n):
    if els[i]=='Ir': print(i,[(els[j],round(np.linalg.norm(P[i]-P[j]),2)) for j in range(n) if 0<np.linalg.norm(P[i]-P[j])<2.5])
EOF
